pub fn valid(value: Interrupt) {
    let tag = value as i16;
    assert!(tag >= -140 && tag <= 145);
    assert!((tag + 140) % 3 == 0);
}

pub fn wrong(value: Interrupt) {
    assert!((value as i16) <= 142);
}

pub fn concrete() {
    valid(Interrupt::V0);
    valid(Interrupt::V95);
}
